using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using RegistrationCompiler;

namespace TaskRunner.Generator;

[Generator(LanguageNames.CSharp)]
public sealed class TaskGenerator : IIncrementalGenerator
{
    private const string AdapterId = "TaskRunner";
    private const string Registry = "global::System.Collections.Generic.List<global::System.Func<global::TaskRunner.IStartupTask>>";

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        var tasks = context.SyntaxProvider.CreateSyntaxProvider(
            static (node, _) => node is ClassDeclarationSyntax { BaseList: not null },
            static (candidate, token) =>
            {
                var type = candidate.SemanticModel.GetDeclaredSymbol(candidate.Node, token) as INamedTypeSymbol;
                var contract = candidate.SemanticModel.Compilation.GetTypeByMetadataName("TaskRunner.IStartupTask");
                return type is { IsAbstract: false } && contract is not null && type.AllInterfaces.Contains(contract, SymbolEqualityComparer.Default)
                    ? type.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat) : null;
            }).Where(name => name is not null).Collect();

        context.RegisterSourceOutput(context.CompilationProvider.Combine(tasks), static (output, input) =>
        {
            var compilation = input.Left;
            var names = input.Right.Distinct(StringComparer.Ordinal).ToArray();
            if (names.Length > 0)
            {
                var statements = names.Select(name => $"target.Add(static () => new {name}());");
                output.AddSource("TaskBindings.g.cs", RegistrationSource.EmitProducer(compilation.Assembly.Name, AdapterId, Registry, statements));
            }

            if (compilation.Options.OutputKind != OutputKind.ConsoleApplication)
                return;
            var imports = RegistrationSource.GetImports(compilation, AdapterId, "tasks", names.Length > 0);
            output.AddSource("GeneratedTasks.g.cs", $$"""
                // <auto-generated/>
                {{string.Join("\n", imports.ExternAliases)}}
                namespace TaskRunner;
                internal static class GeneratedTasks
                {
                    internal static {{Registry}} Create()
                    {
                        var tasks = new {{Registry}}();
                        {{string.Join("\n        ", imports.Calls)}}
                        return tasks;
                    }
                }
                """);
        });
    }
}
